import { gsap } from 'gsap';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec2, length, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new THREE.Group();
  group.name = 'stat-tile-home';

  // ---- depth plane 0: soft grounding shadow (behind card) ----
  const shadowGeo = new THREE.PlaneGeometry(2.1, 1.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new THREE.Color('#000000'),
    transparent: true,
    depthWrite: false,
  });
  const centered = uv().sub(vec2(0.5, 0.5));
  const dist = length(centered);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, dist).mul(0.5);
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0.05, -0.06, -0.18);
  group.add(shadowPlane);

  // ---- depth plane 1: machined card body (subject) ----
  const cardW = 1.6;
  const cardH = 1.05;
  const cardD = 0.14;
  const cardGeo = new THREE.BoxGeometry(cardW, cardH, cardD, 1, 1, 1);
  const cardMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.surface),
    metalness: 0.5,
    roughness: 0.55,
  });
  const card = new THREE.Mesh(cardGeo, cardMat);
  group.add(card);

  // backlit inset readout plate — brightest local element (the "value" field)
  const insetGeo = new THREE.BoxGeometry(cardW * 0.84, cardH * 0.62, 0.02);
  const insetMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.ink),
    metalness: 0.3,
    roughness: 0.55,
    emissive: new THREE.Color(colors.paper),
    emissiveIntensity: 0.35,
  });
  const inset = new THREE.Mesh(insetGeo, insetMat);
  inset.position.set(0, 0.03, cardD / 2 + 0.011);
  group.add(inset);

  // accent focus edge — hidden by default, revealed on hover/focus/click
  const edgeGeo = new THREE.BoxGeometry(cardW + 0.04, cardH + 0.04, 0.02);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 0.0,
    metalness: 0.2,
    roughness: 0.4,
    transparent: true,
    opacity: 0.0,
  });
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -cardD / 2 - 0.01;
  group.add(edge);

  // local rim light — accent-tinted, kept within the intensity cap
  const rim = new THREE.PointLight(new THREE.Color(colors.accent), 0.8, 3.2, 2.0);
  rim.position.set(-0.6, 0.5, 1.1);
  group.add(rim);

  // ---- depth plane 2: decorative machined gear accent (foreground), loaded from GLB ----
  let gearScene = null;
  let gearSpinTween = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    gearScene = gltf.scene;
    gearScene.scale.setScalar(0.26);
    gearScene.position.set(cardW * 0.33, -cardH * 0.3, cardD / 2 + 0.08);
    group.add(gearScene);
    // idle: single slow transform, ~0.15 rad/s
    gearSpinTween = gsap.to(gearScene.rotation, {
      z: Math.PI * 2,
      duration: 41.9,
      repeat: -1,
      ease: 'none',
    });
  }).catch(() => {});

  // ---- text content (render only what the spec actually provides) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (!item?.text) continue;
    const isLabel = item.role === 'label' || item.role === 'caption';
    const node = ctx.fontAtlas.createText(item.text, {
      fontSize: isLabel ? 22 : 46,
      color: isLabel ? colors.paper : colors.paper,
      align: 'center',
    });
    node.position.set(0, isLabel ? -0.24 : 0.1, cardD / 2 + 0.03);
    group.add(node);
    textNodes.push(node);
  }

  // ---- cinematic primitives ----
  const primitiveHandles = [];
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      try {
        const handle = fn(group, prim.params ?? {});
        if (handle) primitiveHandles.push(handle);
      } catch (e) {
        // primitive failure should not break the node
      }
    }
  }

  // ---- interaction timelines ----
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(
    group.position,
    { y: '+=0.15', duration: 0.5, ease: 'power3.out' },
    0
  );
  hoverTl.to(
    edgeMat,
    { opacity: 0.85, emissiveIntensity: 1.2, duration: 0.3, ease: 'power2.out' },
    0
  );
  hoverTl.to(
    insetMat,
    { emissiveIntensity: 0.6, duration: 0.3, ease: 'power2.out' },
    0
  );

  const settleTl = gsap.timeline({ paused: true });

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power4.out' });

  function onPointerOver() {
    hoverTl.play();
  }
  function onPointerOut() {
    hoverTl.reverse();
  }
  function onClick() {
    pressTl.restart();
    ctx.emit('hub-home.select', { nodeId: config.id ?? 'stat-tile-home' });
  }
  function onFocus() {
    edgeMat.opacity = 0.85;
    edgeMat.emissiveIntensity = 1.0;
  }
  function onBlur() {
    edgeMat.opacity = 0.0;
    edgeMat.emissiveIntensity = 0.0;
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onClick,
    onFocus,
    onBlur,
  };

  group.userData.cleanup = () => {
    hoverTl.kill();
    pressTl.kill();
    settleTl.kill();
    if (gearSpinTween) gearSpinTween.kill();

    for (const handle of primitiveHandles) {
      try {
        handle.cleanup?.();
      } catch (e) {
        // ignore
      }
    }

    for (const node of textNodes) {
      group.remove(node);
      node.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    }

    if (gearScene) {
      gearScene.traverse((child) => {
        child.geometry?.dispose?.();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose?.());
          } else {
            child.material.dispose?.();
          }
        }
      });
    }

    shadowGeo.dispose();
    shadowMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    insetGeo.dispose();
    insetMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    rim.dispose?.();
  };

  return group;
}
